import bpy,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];s=bpy.context.scene
props=lambda o,names:{n:getattr(o,n) for n in names}
data=dict(sha256=hashlib.sha256(Path(bpy.data.filepath).read_bytes()).hexdigest(),blender=bpy.app.version_string,renderer=s.render.engine,cycles=props(s.cycles,['device','samples','use_adaptive_sampling','adaptive_threshold','adaptive_min_samples','seed','use_animated_seed','use_denoising','denoiser','max_bounces','diffuse_bounces','glossy_bounces','transmission_bounces','sample_clamp_indirect','blur_glossy']),color=props(s.view_settings,['view_transform','look','exposure','gamma']),output=props(s.render,['resolution_x','resolution_y','resolution_percentage','fps','fps_base','filter_size','use_persistent_data','film_transparent']),lights=[dict(name=o.name,type=o.data.type,energy=o.data.energy,color=list(o.data.color),size=getattr(o.data,'size',None),world_matrix=[list(row) for row in o.matrix_world]) for o in s.objects if o.type=='LIGHT'],images=[dict(name=i.name,type=i.type,path=i.filepath,packed=bool(i.packed_file)) for i in bpy.data.images],fonts=[dict(name=f.name,path=f.filepath,packed=bool(f.packed_file)) for f in bpy.data.fonts],libraries=[l.filepath for l in bpy.data.libraries],materials=len(bpy.data.materials),node_groups=[g.name for g in bpy.data.node_groups],camera=s.camera.name)
(R/'review/render-settings.json').write_text(json.dumps(data,indent=2));print('FINAL_DEPENDENCIES',data['images'],data['fonts'],data['libraries'],flush=True)
